using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Threading;using System.Diagnostics;using System.Collections.Generic;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class Studio59Tests {
 static int n;static void Check(bool ok,string text){if(!ok)throw new Exception(text);n++;Console.WriteLine("PASS "+text);}static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}static IEnumerable<Control> All(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in All(x))yield return y;}}
 static void Pump(int ms=120){var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(4);}}static void Wait(Func<bool> done){var w=Stopwatch.StartNew();while(!done()&&w.ElapsedMilliseconds<15000)Pump(10);Check(done(),"Asynchrone Suche abgeschlossen");}static void Save(Control c,string name){Pump();using(var image=new Bitmap(c.Width,c.Height)){using(var g=Graphics.FromImage(image))g.CopyFromScreen(c.PointToScreen(Point.Empty),Point.Empty,image.Size);image.Save(Path.GetFullPath("verify/"+name+".png"));}}
 [STAThread]static void Main(){Application.EnableVisualStyles();
  var f=new BoxFolder{Name="Country"};f.Songs.AddRange(new[]{new Song{Artist="AC/DC",Title="Thunderstruck",Album="Live",Source="missing1.mp3"},new Song{Artist="Glen Campbell",Title="Sunflower (Live)",Genre="Country",Year="1977",Source="missing2.mp3"},new Song{Artist="Lainey Wilson",Title="4x4xU",Source="missing3.mp3"},new Song{Artist="Beyoncé",Title="Déjà Vu",Source="missing4.mp3"}});
  var index=new LibrarySearchIndex(f.Songs.Select(s=>new LibrarySearchIndex.Entry(f,s)));foreach(string query in new[]{"acdc","Ac/Dc","camp sun","1977 country","lenny wilson","beyonce deja","nothing","Live","4x4xu","SUNFLOWR"}){var expected=f.Songs.Where(s=>LibrarySearch.Matches(s,f.Name,query)).ToArray();var actual=index.Filter(query,false,CancellationToken.None).Select(x=>x.Song).ToArray();Check(expected.SequenceEqual(actual),"Suchindex entspricht bisheriger Teilwort-/Fuzzy-Suche: "+query);}
  var cancel=new CancellationTokenSource();cancel.Cancel();bool canceled=false;try{index.Filter("x",false,cancel.Token);}catch(OperationCanceledException){canceled=true;}Check(canceled,"Überholte Filterung wird abgebrochen");
  var big=new BoxFolder{Name="Big"};for(int i=0;i<20000;i++)big.Songs.Add(new Song{Artist="Artist "+i,Title="Song "+i,Album="Album",Source="not-on-disk-"+i+".mp3"});var large=new LibrarySearchIndex(big.Songs.Select(s=>new LibrarySearchIndex.Entry(big,s)));var timer=Stopwatch.StartNew();large.Filter("artist 123",false,CancellationToken.None);Console.WriteLine("INFO Erstaufbau 20.000 Titel: "+timer.ElapsedMilliseconds+" ms");timer.Restart();large.Filter("song 456",false,CancellationToken.None);Console.WriteLine("INFO Folgefilter 20.000 Titel: "+timer.ElapsedMilliseconds+" ms");Check(large.Filter("not-on-disk-19999",false,CancellationToken.None).Length>0,"Dateinamen ohne Dateizugriff durchsuchbar");
  using(var v=new MainView(Path.GetFullPath("verify/layout59.json"))){var controller=new Controller(v,Path.GetFullPath("verify/backups59"),new Playback(new PlaybackTestDevice()));var p=new Project();p.Folders.Add(f);Call(controller,"ReplaceProject",p,null,true);Check(v.WindowState==FormWindowState.Maximized,"Anwendung startet maximiert");v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1600,1000);v.Location=Point.Empty;Pump();Check(v.Text.Contains(AppIdentity.Version),"Versionsnummer sichtbar");
   var nav=(Panel)Field(v,"studioNavigation");Check(nav.Controls.OfType<Button>().Single(b=>b.Text=="Bibliothek").Top<=15,"Navigation ohne leere Blöcke oberhalb Bibliothek");
   Call(controller,"OpenStudioModule","Einstellungen");Pump();Check(!((Control)Field(v,"studioLibrary")).Visible,"Einstellungen ohne Titelliste und Spaltenauswahl");Check(v.ModuleHost.Height>=((Control)Field(v,"studioCenter")).Height-2,"Einstellungen nutzen volle Höhe");Save(v,"einstellungen59");Call(controller,"OpenStudioModule","Bibliothek");Check(((Control)Field(v,"studioLibrary")).Visible&&v.Songs.Rows.Count==4,"Bibliothek und Titel nach Einstellungen erhalten");
   Call(controller,"OpenStudioModule","Konvertierung");Pump();var controls=All(v.ModuleHost).ToArray();var combo=controls.OfType<ComboBox>().Single();var fields=controls.OfType<TextBox>().Take(2).ToArray();Check(combo is StudioComboBox&&combo.DrawMode==DrawMode.OwnerDrawFixed,"Tag-Dropdown im Studio-Design einschließlich Auswahlliste");Check(fields.All(x=>x.Height==combo.Height&&x.BackColor==combo.BackColor&&x.Font.Equals(combo.Font)),"Alle drei Tag-Felder gleich hoch, dunkel und gleiche Schrift");Save(v,"tagkonvertierung59");combo.DroppedDown=true;Pump();Save(v,"tagdropdown59");combo.DroppedDown=false;
   Call(controller,"OpenStudioModule","Bibliothek");v.SearchBox.Text="Sunflower";Wait(()=>v.Songs.Rows.Count==1&&((Song)v.Songs.Rows[0].Tag).Artist=="Glen Campbell");
   var clear=All(v).OfType<StudioActionButton>().Single(b=>b.Symbol=="Clear");clear.PerformClick();Pump(250);Check(v.SearchBox.Text=="Sunflower"&&v.Songs.Rows.Count==1,"X beendet Mikrofonsteuerung ohne Suchtext/Ergebnis zu löschen");
   v.SearchBox.Text="ACDC";v.SearchBox.Text="no-result";v.SearchBox.Text="Lainey";Wait(()=>v.Songs.Rows.Count==1&&((Song)v.Songs.Rows[0].Tag).Artist=="Lainey Wilson");Pump(500);Check(v.Songs.Rows.Count==1&&((Song)v.Songs.Rows[0].Tag).Artist=="Lainey Wilson","Ältere Suche überschreibt neuere Ergebnisse nicht");
   v.SearchBox.Clear();Wait(()=>v.Songs.Rows.Count==4);Call(controller,"HandleVoice",new object[]{new[]{"Glen Campbell"}});Wait(()=>v.Songs.Rows.Count==1&&((Song)v.Songs.Rows[0].Tag).Artist=="Glen Campbell");clear.PerformClick();Pump(250);Check(v.SearchBox.Text=="Glen Campbell"&&v.Songs.Rows.Count==1,"Erkannter Suchtext und Suchtreffer nach X erhalten");
   var dynamic=new Panel();var check=new CheckBox{Text="Test"};dynamic.Controls.Add(check);v.ModuleHost.Controls.Add(dynamic);Check(check.FlatStyle==FlatStyle.Flat&&!check.UseVisualStyleBackColor&&check.BackColor==ModernTheme.Navy,"Nachträgliche Checkbox automatisch dunkel");dynamic.Dispose();
   var many=new Project();many.Folders.Add(new BoxFolder{Name="Large",Songs=big.Songs.Take(5000).ToList()});v.SearchBox.Clear();Call(controller,"ReplaceProject",many,null,true);int ticks=0;using(var heartbeat=new System.Windows.Forms.Timer{Interval=10}){heartbeat.Tick+=(s,e)=>ticks++;heartbeat.Start();v.SearchBox.Text="Artist";Wait(()=>Field(controller,"librarySearchCancel")==null&&v.Songs.Rows.Count==5000);heartbeat.Stop();Check(ticks>5,"UI verarbeitet Ereignisse während Suche und 5.000 Trefferaufbau");}
   v.SearchBox.Text="Song";bool replaced=false;using(var interrupt=new System.Windows.Forms.Timer{Interval=5}){interrupt.Tick+=(s,e)=>{if((int)Field(controller,"libraryRenderGeneration")<0)return;interrupt.Stop();replaced=true;v.SearchBox.Clear();Call(controller,"ReplaceProject",p,null,true);};interrupt.Start();Wait(()=>replaced);Pump(300);Check(v.Songs.Rows.Count==4,"Projektwechsel während Trefferaufbau verwirft alte Ergebniszeilen");}v.Close();
  }
  Console.WriteLine("BESTANDEN "+n+" Prüfungen. Native Windows-Mikrofonhardware und Scrollbar-Nachrichten hier nicht ausgeführt.");
 }
}
